/**
 * The wide-query policy (M-A4). Internal-relief: a query whose slot demand blows the 60-slot budget only through
 * internal-only variables compiles natively after greedy island demotion. Genuinely wide: a query projecting more than
 * 60 live variables stays on the documented GENERIC_HOSTED policy, census-tracked. The tests distinguish the two.
 */
public class LmdbNativeWideQueryTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String ISLANDS_FLAG = "rdf4j.lmdb.islands.enabled";
	private static final int GROUPS = 24;

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			ValueFactory vf = conn.getValueFactory();
			// one hub resource with a 3-hop chain per group: x/y/z of each group are internal-only
			for (int i = 0; i < GROUPS; i++) {
				conn.add(vf.createIRI(EX, "hub"), vf.createIRI(EX, "p" + i), vf.createIRI(EX, "x" + i));
				conn.add(vf.createIRI(EX, "x" + i), vf.createIRI(EX, "q" + i), vf.createIRI(EX, "y" + i));
				conn.add(vf.createIRI(EX, "y" + i), vf.createIRI(EX, "r" + i), vf.createLiteral(i));
			}
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	/** ~73 variables total, one projected: internal-only names must not cost the native engine the whole root. */
	private String internalHeavyQuery() {
		StringBuilder query = new StringBuilder("SELECT ?s WHERE { ");
		for (int i = 0; i < GROUPS; i++) {
			query.append("{ ?s <")
					.append(EX)
					.append("p")
					.append(i)
					.append("> ?x")
					.append(i)
					.append(" . ?x")
					.append(i)
					.append(" <")
					.append(EX)
					.append("q")
					.append(i)
					.append("> ?y")
					.append(i)
					.append(" . ?y")
					.append(i)
					.append(" <")
					.append(EX)
					.append("r")
					.append(i)
					.append("> ?z")
					.append(i)
					.append(" FILTER(BOUND(?x")
					.append(i)
					.append(")) } ");
		}
		return query.append("}").toString();
	}

	/** 64 projected variables bound through OPTIONAL arms: genuinely wide output. */
	private String genuinelyWideQuery() {
		StringBuilder query = new StringBuilder("SELECT ?s");
		for (int i = 0; i < 64; i++) {
			query.append(" ?w").append(i);
		}
		query.append(" WHERE { ?s <").append(EX).append("p0> ?x0 ");
		for (int i = 0; i < 64; i++) {
			query.append("OPTIONAL { ?s <").append(EX).append("p").append(i).append("> ?w").append(i).append(" } ");
		}
		return query.append("}").toString();
	}

	/** Exactly {@code projectedNames} live output bindings: ?s plus w0..wN. */
	private String boundaryQuery(int projectedNames) {
		StringBuilder query = new StringBuilder("SELECT ?s");
		for (int i = 0; i < projectedNames - 1; i++) {
			query.append(" ?w").append(i);
		}
		query.append(" WHERE { ?s <").append(EX).append("p0> ?w0 ");
		for (int i = 1; i < projectedNames - 1; i++) {
			query.append("OPTIONAL { ?s <").append(EX).append("p").append(i).append("> ?w").append(i).append(" } ");
		}
		return query.append("}").toString();
	}

	@Test
	public void internalHeavyQueryDemotesToNativeHybrid() {
		String query = internalHeavyQuery();
		List<String> generic = genericRows(query);
		assertThat(generic).hasSize(1);

		withProperty(ISLANDS_FLAG, "true", () -> {
			long demotionsBefore = LmdbNativeAggregateCompiler.WIDE_QUERY_DEMOTIONS.get();
			List<String> hybrid = rows(query);
			assertThat(hybrid).isEqualTo(generic);
			assertThat(LmdbNativeAggregateCompiler.WIDE_QUERY_DEMOTIONS.get() - demotionsBefore)
					.as("the slot-starved root must be rescued by internal-variable island demotion")
					.isEqualTo(1);
		});
	}

	@Test
	public void internalHeavyQueryWithoutIslandsStaysHostedAndCorrect() {
		String query = internalHeavyQuery();
		withProperty(ISLANDS_FLAG, "false", () -> {
			long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
			List<String> hosted = rows(query);
			assertThat(hosted).isEqualTo(genericRows(query));
			assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get() - hostedBefore).isEqualTo(1);
		});
	}

	@Test
	public void genuinelyWideQueryStaysHostedUnderTheDocumentedPolicy() {
		String query = genuinelyWideQuery();
		withProperty(ISLANDS_FLAG, "true", () -> {
			long wideBefore = LmdbNativeAggregateCompiler.WIDE_OUTPUT_HOSTED.get();
			long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
			List<String> wide = rows(query);
			assertThat(wide).isEqualTo(genericRows(query));
			assertThat(LmdbNativeAggregateCompiler.WIDE_OUTPUT_HOSTED.get() - wideBefore)
					.as("the census must distinguish genuinely wide outputs from internal-relief cases")
					.isGreaterThanOrEqualTo(1);
			assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get() - hostedBefore)
					.as("genuinely wide outputs follow the documented GENERIC_HOSTED policy")
					.isEqualTo(1);
		});
	}

	@Test
	public void sixtyLiveSlotsRemainNative() {
		String query = boundaryQuery(60);
		long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		long islandsBefore = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
		List<String> nativeRows = rows(query);
		assertThat(nativeRows).isEqualTo(genericRows(query)).hasSize(1);
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get()).isEqualTo(hostedBefore);
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get()).isEqualTo(islandsBefore);
	}

	@Test
	public void sixtyOneLiveSlotsUseOnlyCapacityOutcome() {
		String query = boundaryQuery(61);
		assertThat(explain(query)).contains("CAPACITY_MAX_NATIVE_SLOTS");
		long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		List<String> hostedRows = rows(query);
		assertThat(hostedRows).isEqualTo(genericRows(query)).hasSize(1);
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get() - hostedBefore).isEqualTo(1);
	}

	private String explain(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return conn.prepareTupleQuery(query).explain(Explanation.Level.Optimized).toString();
		}
	}

	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(LmdbNativeWideQueryTest::render)
					.collect(Collectors.toList());
		}
	}

	private List<String> genericRows(String query) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			System.setProperty(NATIVE_FLAG, "false");
			return rows(query);
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private void withProperty(String name, String value, Runnable action) {
		String previous = System.getProperty(name);
		try {
			System.setProperty(name, value);
			action.run();
		} finally {
			if (previous == null) {
				System.clearProperty(name);
			} else {
				System.setProperty(name, previous);
			}
		}
	}

	private static String render(BindingSet bindings) {
		return bindings.getBindingNames()
				.stream()
				.sorted()
				.map(name -> name + "=" + bindings.getValue(name))
				.collect(Collectors.joining(", "));
	}
}
